   *
   * 모든 상태에서 가능 (Router가 로컬/서버 자동 분기)
   */
  read: {
    online_active: {
      allowed: true,
      mode: 'full',
    },
    online_inactive: {
      allowed: true,
      mode: 'full',
    },
    offline_active: {
      allowed: true,
      mode: 'full', // Router가 로컬 DB 읽기 처리
    },
    offline_inactive: {
      allowed: true,
      mode: 'full', // Router가 처리 (로컬 캐시 or 에러)
      reason: '수정하려면 여행을 활성화해주세요',
    },
