    offline_active: {
      allowed: true,
      mode: 'manual-only',
      validation: {
        allowed: ['title', 'scheduledAt', 'location'],
        blocked: ['latitude', 'longitude'],
      },
    },
    offline_inactive: {
      allowed: false,
      reason: '여행을 활성화해주세요',
    },
  },

  /**
   * Schedule 삭제
   */
  delete: {
    online_active: {
      allowed: true,
      mode: 'full',
    },
    online_inactive: {
      allowed: true,
      mode: 'full',
    },
    offline_active: {
      allowed: true,
      mode: 'full',
    },
    offline_inactive: {
      allowed: false,
      reason: '여행을 활성화해주세요',
    },
  },
};

// ============================================================================
// Expense Policies
// ============================================================================

export const EXPENSE_POLICIES: ExpensePolicies = {
  /**
   * Expense 생성
   *
   * 오프라인 활성화: Manual Input 모드 (일정 연결 제한)
   */
  create: {
    online_active: {
      allowed: true,
      mode: 'full',
      validation: {
        required: ['title', 'amount', 'currency', 'category', 'date'],
        optional: ['scheduleId', 'receiptUrl'],
      },
    },
    online_inactive: {
      allowed: true,
      mode: 'full',
      validation: {
        required: ['title', 'amount', 'currency', 'category', 'date'],
        optional: ['scheduleId', 'receiptUrl'],
      },
    },
    offline_active: {
      allowed: true,
      mode: 'manual-only',
      reason: '오프라인에서는 일정을 연결할 수 없어요. 직접 입력해주세요.',
      validation: {
        required: ['title', 'amount', 'currency', 'category', 'date'],
        optional: ['scheduleId'],
        enforced: {
          receiptUrl: null,
        },
      },
    },
    offline_inactive: {
      allowed: false,
      reason: '여행을 활성화해주세요',
    },
  },

  /**
   * Expense 조회
   */
  read: {
    online_active: {
      allowed: true,
      mode: 'full',
    },
    online_inactive: {
      allowed: true,
      mode: 'full',
    },
    offline_active: {
      allowed: true,
      mode: 'full', // Router가 로컬 DB 읽기 처리
    },
    offline_inactive: {
      allowed: true,
      mode: 'full', // Router가 처리
    },
  },

  /**
   * Expense 수정
   */
  update: {
    online_active: {
      allowed: true,
      mode: 'full',
    },
    online_inactive: {
      allowed: true,
      mode: 'full',
    },
    offline_active: {
      allowed: true,
      mode: 'manual-only',
      reason: '오프라인에서는 일정을 연결할 수 없어요.',
      validation: {
        allowed: ['title', 'amount', 'currency', 'category', 'date'],
        blocked: ['receiptUrl'],
      },
    },
    offline_inactive: {
      allowed: false,
      reason: '여행을 활성화해주세요',
    },
  },

  /**
   * Expense 삭제
   */
  delete: {
    online_active: {
      allowed: true,
      mode: 'full',
    },
    online_inactive: {
      allowed: true,
      mode: 'full',
    },
    offline_active: {
      allowed: true,
      mode: 'full',
    },
    offline_inactive: {
      allowed: false,
      reason: '여행을 활성화해주세요',
    },
  },
};

// ============================================================================
// Service Layer Policies
// ============================================================================

export const SERVICE_POLICIES: ServicePolicies = {
  online_active: {
    mapProvider: 'google',
    searchMode: 'api',
    syncStrategy: 'immediate',
    uiMode: 'full',
  },
  online_inactive: {
    mapProvider: 'google',
    searchMode: 'api',
    syncStrategy: 'immediate',
    uiMode: 'full',
  },
  offline_active: {
    mapProvider: 'mapbox',
    searchMode: 'disabled',
    syncStrategy: 'background',
    uiMode: 'limited',
  },
  offline_inactive: {
    mapProvider: 'none',
    searchMode: 'disabled',
    syncStrategy: 'disabled',
    uiMode: 'readonly',
  },
};

// ============================================================================
// Debugging Helper
// ============================================================================

/**
 * CRUD 중심 뷰 Helper
 *
 * 특정 entity의 operation이 4가지 state에서 어떻게 동작하는지 확인
 *
 * @example
 * ```ts
 * console.table(getCRUDPolicyByOperation('schedule', 'create'));
 * // ┌─────────────────┬─────────┬──────────────┬────────────────┐
 * // │     State       │ allowed │     mode     │     reason     │
 * // ├─────────────────┼─────────┼──────────────┼────────────────┤
 * // │ online_active   │  true   │    full      │       -        │
 * // │ offline_active  │  true   │ manual-only  │  장소 검색...  │
 * // └─────────────────┴─────────┴──────────────┴────────────────┘
 * ```
 */
export function getCRUDPolicyByOperation(
  entity: 'trip' | 'schedule' | 'expense',
  operation: 'create' | 'read' | 'update' | 'delete',
): Record<string, CRUDPermission> {
  const policyMap = {
    trip: TRIP_POLICIES,
    schedule: SCHEDULE_POLICIES,
    expense: EXPENSE_POLICIES,
  };

  return policyMap[entity][operation];
}

