import { useState, useMemo, useCallback } from 'react';
import { View, Alert } from 'react-native';
import { MobileHeader } from '@/shared/components';
import { TripSelector } from '@/entities/trip';
import { useGetSchedules, useDeleteSchedule } from '@/entities/schedule';
import { useGetTrips } from '@/entities/trip';
import { useTripStore } from '@/shared/store';
import { Pressable } from '@repo/ui';
import { Map, List } from 'lucide-react-native';
import { ScheduleListView } from '@/features/schedule/schedule-list-view';
import { ScheduleMapViewContainer } from '@/features/schedule/schedule-map-view';
import { ScheduleMenu } from '@/features/schedule/schedule-menu';
import { UpdateScheduleDrawer } from '@/features/schedule/update-schedule';
import { formatISOToLocalDate, formatISOToLocalTime } from '@/shared/lib/datetime';

type ViewMode = 'list' | 'map';

interface ScheduleByDate {
  date: string;
  dateLabel: string;
  schedules: Array<{
    id: string;
    tripId: string;
    scheduledAt: string;
    time: string;
    title: string;
    location: string;
    address?: string | null;
    latitude?: string | null;
    longitude?: string | null;
    expense?: string;
    expenseCount?: number;
  }>;
}

export default function ScheduleScreen() {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const { selectedTripId } = useTripStore();
  const [isScheduleMenuOpen, setIsScheduleMenuOpen] = useState(false);
  const [isUpdateDrawerOpen, setIsUpdateDrawerOpen] = useState(false);
  const [selectedSchedule, setSelectedSchedule] = useState<{
    id: string;
    tripId: string;
    scheduledAt: string;
    time: string;
    title: string;
    location: string;
    address?: string | null;
    latitude?: string | null;
    longitude?: string | null;
    expense?: string;
    expenseCount?: number;
  } | null>(null);
  const [buttonPosition, setButtonPosition] = useState<
    { x: number; y: number; width: number; height: number } | undefined
  >(undefined);

  const { data: trips = [] } = useGetTrips();
  const { data: schedules = [], isLoading, refetch } = useGetSchedules(selectedTripId || '');
  const { mutate: deleteSchedule } = useDeleteSchedule();

  // Pull-to-Refresh
  const [refreshing, setRefreshing] = useState(false);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    try {
      await refetch();
    } finally {
      setRefreshing(false);
    }
  }, [refetch]);

  // 선택된 여행 정보
  const selectedTrip = trips.find((trip: { id: string }) => trip.id === selectedTripId);

  // 여행 날짜 범위에서 모든 날짜 생성
  const generateDateRange = (): string[] => {
    if (!selectedTrip?.startDate || !selectedTrip?.endDate) return [];

    const dates: string[] = [];
    const start = new Date(selectedTrip.startDate);
    const end = new Date(selectedTrip.endDate);

    const current = new Date(start);
    while (current <= end) {
      dates.push(current.toISOString().split('T')[0]);
      current.setDate(current.getDate() + 1);
    }

    return dates;
  };

  const dateRange = generateDateRange();

  // 일정 메뉴 핸들러
  const handleScheduleMenuPress = (
    schedule: {
      id: string;
      tripId: string;
      scheduledAt: string;
      time: string;
      title: string;
      location: string;
      address?: string | null;
      latitude?: string | null;
      longitude?: string | null;
      expense?: string;
      expenseCount?: number;
    },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    event: any,
  ) => {
    setSelectedSchedule(schedule);
    // 버튼 위치 측정
    event.currentTarget.measure((x: number, y: number, width: number, height: number, pageX: number, pageY: number) => {
      setButtonPosition({ x: pageX, y: pageY, width, height });
    });
    setIsScheduleMenuOpen(true);
  };

  const handleEditSchedule = () => {
    setIsUpdateDrawerOpen(true);
  };

  const handleDeleteSchedule = () => {
    if (!selectedSchedule) return;

    Alert.alert(
      '일정 삭제',
      `"${selectedSchedule.title}" 일정을 삭제하시겠습니까?`,
      [
        {
          text: '취소',
          style: 'cancel',
        },
        {
          text: '삭제',
          style: 'destructive',
          onPress: () => {
            deleteSchedule(selectedSchedule.id, {
              onSuccess: () => {
                Alert.alert('성공', '일정이 삭제되었습니다.');
                setIsScheduleMenuOpen(false);
                setSelectedSchedule(null);
                setButtonPosition(undefined);
              },
              onError: () => {
                Alert.alert('오류', '일정 삭제에 실패했습니다.');
              },
            });
          },
        },
      ],
      { cancelable: true },
    );
  };

  // 날짜별로 일정 그룹화
  const schedulesByDate: ScheduleByDate[] = useMemo(() => {
    return dateRange.map((date) => {
      const daySchedules = schedules
        .filter((schedule) => {
          return formatISOToLocalDate(schedule.scheduledAt) === date;
        })
        .map((schedule) => {
          return {
            id: schedule.id,
            tripId: schedule.tripId,
            scheduledAt: schedule.scheduledAt,
            time: formatISOToLocalTime(schedule.scheduledAt),
            title: schedule.title,
            location: schedule.location || '',
            address: schedule.address,
            latitude: schedule.latitude,
            longitude: schedule.longitude,
          };
        });

      return {
        date,
        dateLabel: date,
        schedules: daySchedules,
      };
    });
  }, [dateRange, schedules]);

  return (
    <View className='flex-1 bg-background'>
      {/* Header */}
      <MobileHeader
        title='일정'
        rightAction={
          <View className='flex-row items-center gap-2xs'>
            {/* <Pressable
              variant='ghost'
              className='h-10 w-10 items-center justify-center rounded-full active:bg-muted'
              accessibilityRole='button'
              accessibilityLabel='메뉴 열기'
            >
              <Menu size={20} color='hsl(0, 0%, 12%)' strokeWidth={2} />
            </Pressable> */}
            <Pressable
              variant='ghost'
              className='h-10 w-10 items-center justify-center rounded-full active:bg-muted'
              onPress={() => setViewMode(viewMode === 'list' ? 'map' : 'list')}
              accessibilityRole='button'
              accessibilityLabel={viewMode === 'list' ? '지도 보기로 전환' : '목록 보기로 전환'}
            >
              {viewMode === 'list' ? (
                <Map size={20} color='hsl(0, 0%, 12%)' strokeWidth={2} />
              ) : (
                <List size={20} color='hsl(0, 0%, 12%)' strokeWidth={2} />
              )}
            </Pressable>
          </View>
        }
      />

      {/* Current Trip Selector - Sticky */}
      <TripSelector className='border-b border-card-border bg-background px-md py-sm' />

      {/* Content */}
      {viewMode === 'list' ? (
        <ScheduleListView
          schedulesByDate={schedulesByDate}
          selectedTripId={selectedTripId}
          isLoading={isLoading}
          hasTrip={!!selectedTrip}
          hasDates={!!(selectedTrip?.startDate && selectedTrip?.endDate)}
          onScheduleMenuPress={handleScheduleMenuPress}
          refreshing={refreshing}
          onRefresh={onRefresh}
        />
      ) : (
        <ScheduleMapViewContainer
          tripId={selectedTripId || ''}
          dateRange={dateRange}
          schedulesByDate={schedulesByDate}
          initialDate={dateRange[0] || null}
        />
      )}

      {/* Schedule Menu */}
      <ScheduleMenu
        isOpen={isScheduleMenuOpen}
        onClose={() => {
          setIsScheduleMenuOpen(false);
          setButtonPosition(undefined);
          // selectedSchedule는 드로어에서 사용하므로 여기서 초기화하지 않음
        }}
        onEdit={handleEditSchedule}
        onDelete={handleDeleteSchedule}
        buttonPosition={buttonPosition}
      />

      {/* Update Schedule Drawer */}
      <UpdateScheduleDrawer
        isOpen={isUpdateDrawerOpen}
        onClose={() => {
          setIsUpdateDrawerOpen(false);
          setSelectedSchedule(null); // 드로어를 닫을 때 초기화
        }}
        scheduleData={
          selectedSchedule
            ? {
                id: selectedSchedule.id,
                tripId: selectedSchedule.tripId,
                title: selectedSchedule.title,
                date: formatISOToLocalDate(selectedSchedule.scheduledAt),
                time: selectedSchedule.time,
                location: selectedSchedule.location,
                address: selectedSchedule.address,
                latitude: selectedSchedule.latitude,
                longitude: selectedSchedule.longitude,
              }
            : null
        }
      />
    </View>
  );
}
import { View, Text, ScrollView, Alert, RefreshControl } from 'react-native';
import { Container, Stack, ExpenseCard, MobileHeader } from '@/shared/components';
import { TripSelector } from '@/entities/trip';
import { useGetTripExpenses, useDeleteExpense } from '@/entities/expense';
import { useGetTrips } from '@/entities/trip';
import { Pressable } from '@repo/ui';
import { useRouter } from 'expo-router';
import { useTripStore } from '@/shared/store';
import { useMemo, useState, useCallback } from 'react';
import { ExpenseMenu } from '@/features/expense/expense-menu';
import { UpdateExpenseDrawer } from '@/features/expense/update-expense';
import { formatISOToLocalDate } from '@/shared/lib/datetime';
import { groupExpensesByCurrency, formatCurrencyDisplay, getCurrencyFractionDigits } from '@/shared/lib/currency';
import type { Expense } from '@/entities/expense';

export default function ExpensesScreen() {
  const router = useRouter();
  const { selectedTripId } = useTripStore();
  const [isExpenseMenuOpen, setIsExpenseMenuOpen] = useState(false);
  const [isUpdateDrawerOpen, setIsUpdateDrawerOpen] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [buttonPosition, setButtonPosition] = useState<
    { x: number; y: number; width: number; height: number } | undefined
  >(undefined);

  // useDeleteExpense mutation hook
  const { mutate: deleteExpense } = useDeleteExpense();

  // 여행 데이터 조회
  const { data: trips = [] } = useGetTrips();
  const selectedTrip = trips.find((trip) => trip.id === selectedTripId);

  // 실제 경비 데이터 조회 (tripId 필수)
  const { data: expenses = [], isLoading, refetch } = useGetTripExpenses(selectedTripId || '');

  // Pull-to-Refresh
  const [refreshing, setRefreshing] = useState(false);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    try {
      await refetch();
    } finally {
      setRefreshing(false);
    }
  }, [refetch]);

  // 여행 날짜 범위에서 모든 날짜 생성
  const generateDateRange = (): string[] => {
    if (!selectedTrip?.startDate || !selectedTrip?.endDate) return [];

    const dates: string[] = [];
    const start = new Date(selectedTrip.startDate);
    const end = new Date(selectedTrip.endDate);

    const current = new Date(start);
    while (current <= end) {
      dates.push(current.toISOString().split('T')[0]);
      current.setDate(current.getDate() + 1);
    }

    return dates;
  };

  const dateRange = generateDateRange();

  // 날짜별로 경비 매칭 (여행 기간 밖 경비도 포함)
  const expensesByDate = useMemo(() => {
    // ✅ TIME_ARCHITECTURE_GUIDE: ISO datetime → Local date
    // expense.date: "2024-03-15T00:00:00.000Z" → "2024-03-15"
    const allDates = new Set([...dateRange, ...expenses.map((e) => formatISOToLocalDate(e.date))]);
    const sortedDates = Array.from(allDates).sort();

    // 모든 날짜 표시
    const dateGroups = sortedDates.map((date) => {
      const dayExpenses = expenses.filter((expense) => formatISOToLocalDate(expense.date) === date);
      const isInTripRange = dateRange.includes(date);

      return {
        date,
        dateLabel: date,
        items: dayExpenses,
        isInTripRange, // 여행 기간 내 날짜인지 표시
      };
    });

    // 여행 기간 외 항목을 맨 위로, 나머지는 날짜 순서대로 정렬
    const outsideTripRange = dateGroups.filter((group) => !group.isInTripRange);
    const insideTripRange = dateGroups.filter((group) => group.isInTripRange);

    return [...outsideTripRange, ...insideTripRange];
  }, [dateRange, expenses]);

  // ✅ CURRENCY_POLICY: 통화별 경비 그룹핑 (baseCurrency 우선)
  const expensesByCurrency = useMemo(
    () => groupExpensesByCurrency(expenses, selectedTrip?.baseCurrency),
    [expenses, selectedTrip?.baseCurrency],
  );

  // 경비 메뉴 핸들러
  const handleExpenseMenuPress = (
    expense: Expense,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    event: any,
  ) => {
    setSelectedExpense(expense);
    // 버튼 위치 측정
    event.currentTarget.measure((x: number, y: number, width: number, height: number, pageX: number, pageY: number) => {
      setButtonPosition({ x: pageX, y: pageY, width, height });
    });
    setIsExpenseMenuOpen(true);
  };

  const handleEditExpense = () => {
    setIsUpdateDrawerOpen(true);
  };

  const handleDeleteExpense = () => {
    if (!selectedExpense) return;

    Alert.alert('경비 삭제', `"${selectedExpense.title}" 경비를 삭제하시겠습니까?`, [
      {
        text: '취소',
        style: 'cancel',
      },
      {
        text: '삭제',
        style: 'destructive',
        onPress: () => {
          // ✅ Selective Local-First: 로컬 DB Soft Delete + sync_queue 기록
          deleteExpense(selectedExpense.id, {
            onSuccess: () => {
              Alert.alert('성공', '경비가 삭제되었습니다.');
              setSelectedExpense(null);
            },
            onError: () => {
              Alert.alert('오류', '경비 삭제에 실패했습니다.');
            },
          });
        },
      },
    ]);
  };

  return (
    <View className='flex-1 bg-background'>
      {/* Header */}
      <MobileHeader
        title='경비'
        // rightAction={
        //   <Pressable
        //     variant='ghost'
        //     className='h-10 w-10 items-center justify-center'
        //     onPress={() => {
        //       // TODO: Open camera
        //       console.log('Open camera');
        //     }}
        //     accessibilityRole='button'
        //     accessibilityLabel='영수증 스캔 카메라 열기'
        //   >
        //     <Camera size={20} color='hsl(0, 0%, 12%)' strokeWidth={2} />
        //   </Pressable>
        // }
      />

      {/* Current Trip Selector - Sticky */}
      <TripSelector className='border-b border-card-border bg-background px-md py-sm' />

      <ScrollView className='flex-1' refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}>
        <Container>
          <Stack direction='vertical' gap='md' className='py-sm'>
            {/* ✅ CURRENCY_POLICY: 통화별 경비 표시 */}
            <View className='flex-col gap-sm rounded-lg bg-muted p-md'>
              <Text className='text-label text-muted-foreground'>통화별 경비</Text>
              {expensesByCurrency.length > 0 ? (
                <View className='flex-col gap-xs'>
                  {expensesByCurrency.map(({ currency, amount }, index) => {
                    const isFirstCurrencyGroup = index === 0;

                    return (
                      <View key={currency} className='flex-row items-baseline justify-between'>
                        {/* 주 통화 (첫 번째)는 강조 */}
                        <Text
                          className={
                            isFirstCurrencyGroup
                              ? 'text-display-medium text-primary'
                              : 'text-title-large text-foreground'
                          }
                        >
                          {currency} {amount.toFixed(getCurrencyFractionDigits(currency))}
                        </Text>
                        {isFirstCurrencyGroup && <Text className='text-label text-muted-foreground'>주 통화</Text>}
                      </View>
                    );
                  })}
                </View>
              ) : (
                <Text className='text-display-medium text-muted-foreground'>
                  {formatCurrencyDisplay(0, selectedTrip?.baseCurrency || 'USD')}
                </Text>
              )}
            </View>

            {/* Loading State */}
            {isLoading && (
              <View className='flex-1 items-center justify-center py-xl'>
                <Text className='text-body text-muted-foreground'>경비를 불러오는 중...</Text>
              </View>
            )}

            {/* Empty State - 여행이 없거나 날짜가 없을 때 */}
            {!isLoading && !selectedTrip && (
              <View className='flex-1 items-center justify-center py-xl'>
                <Text className='text-body text-muted-foreground'>여행을 선택해주세요</Text>
              </View>
            )}

            {!isLoading && selectedTrip && expensesByDate.length === 0 && (
              <View className='flex-1 items-center justify-center py-xl'>
                <Text className='text-body text-muted-foreground'>경비를 추가해보세요</Text>
              </View>
            )}

            {/* Expense List by Date - 경비가 있는 모든 날짜 표시 */}
            {!isLoading &&
              expensesByDate.length > 0 &&
              expensesByDate.map((group) => (
                <View key={group.date} className='flex-col gap-sm'>
                  {/* Date Header */}
                  <View className='flex-row items-center justify-between'>
                    <View className='flex-row items-center gap-2xs'>
                      <Text className='text-title-large text-foreground'>{group.dateLabel}</Text>
                      <View className='rounded-full bg-muted px-xs py-3xs'>
                        <Text className='text-label text-foreground'>{group.items.length}개</Text>
                      </View>
                      {!group.isInTripRange && (
                        <View className='rounded-full bg-destructive/10 px-xs py-3xs'>
                          <Text className='text-label text-destructive'>여행 기간 외</Text>
                        </View>
                      )}
                    </View>
                    <Pressable
                      variant='outline'
                      className='flex-row items-center gap-3xs rounded-md border border-card-border bg-card px-xs py-3xs active:bg-muted'
                      onPress={() => {
                        if (selectedTripId) {
                          router.push(`/create-expense?tripId=${selectedTripId}&date=${group.date}`);
                        } else {
                          console.log('여행을 먼저 선택해주세요');
                        }
                      }}
                    >
                      <Text className='text-label text-foreground'>추가</Text>
                    </Pressable>
                  </View>

                  {/* Expense Cards or Empty State */}
                  {group.items.length > 0 ? (
                    group.items.map((expense) => (
                      <ExpenseCard
                        key={expense.id}
                        title={expense.title}
                        amount={expense.amount}
                        currency={expense.currency}
                        category={expense.category}
                        hasReceipt={expense.hasReceipt}
                        isPending={false}
                        onPress={() => {
                          router.push({
                            pathname: '/expense-detail/[id]',
                            params: { id: expense.id, tripId: expense.tripId },
                          });
                        }}
                        onMenuPress={(event) => handleExpenseMenuPress(expense, event)}
                      />
                    ))
                  ) : (
                    <View className='rounded-lg border border-dashed border-card-border bg-muted/30 px-md py-lg'>
                      <Text className='text-body text-center text-muted-foreground'>이 날의 경비를 추가해보세요</Text>
                    </View>
                  )}
                </View>
              ))}
          </Stack>
        </Container>
      </ScrollView>

      {/* Expense Menu */}
      <ExpenseMenu
        isOpen={isExpenseMenuOpen}
        onClose={() => {
          setIsExpenseMenuOpen(false);
          setButtonPosition(undefined);
        }}
        onEdit={handleEditExpense}
        onDelete={handleDeleteExpense}
        buttonPosition={buttonPosition}
      />

      {/* Update Expense Drawer */}
      <UpdateExpenseDrawer
        isOpen={isUpdateDrawerOpen}
        onClose={() => {
          setIsUpdateDrawerOpen(false);
          setSelectedExpense(null);
        }}
        expenseData={
          selectedExpense
            ? {
                id: selectedExpense.id,
                title: selectedExpense.title,
                amount: selectedExpense.amount,
                currency: selectedExpense.currency,
                category: selectedExpense.category,
                date: selectedExpense.date,
                scheduleId: selectedExpense.scheduleId ?? undefined,
                tripId: selectedExpense.tripId,
              }
            : null
        }
      />
    </View>
  );
}
import { useState } from 'react';
import { View, Text } from 'react-native';
import { Plane, ChevronDown, Check, WifiOff } from 'lucide-react-native';
import { Badge, Drawer, Pressable } from '@repo/ui';
import { useGetTrips } from '../data';
import { useGetActiveTrip } from '../data/useGetTripActivation';
import { selectMainTrip } from '../utils';
import { useTripStore } from '@/shared/store';
import type { TripData } from '../model';

interface Trip {
  value: string;
  label: string;
  isMain?: boolean;
  isActivated?: boolean;
  activationStatus?: 'preparing' | 'ready';
}

interface TripSelectorProps {
  className?: string;
}

/**
 * TripSelector - 현재 여행 선택 컴포넌트
 *
 * packages/ui의 Select Compound Component를 조합하여 만든
 * 여행 선택 특화 컴포넌트입니다.
 *
 * 실제 여행 데이터를 API에서 가져와서 표시하며,
 * 메인 여행은 자동으로 식별되어 뱃지로 표시됩니다.
 * 일정, 경비 등 화면 상단에 sticky 형태로 배치되어
 * 현재 선택된 여행을 표시하고 변경할 수 있습니다.
 *
 * @example
 * <TripSelector
 *   onTripChange={(trip) => console.log('Selected:', trip)}
 * />
 */
export function TripSelector({ className = '' }: TripSelectorProps) {
  // ✨ Zustand 전역 상태
  const { selectedTripId, setSelectedTripId } = useTripStore();
  const [isOpen, setIsOpen] = useState(false);

  // 실제 여행 데이터 가져오기
  const { data: allTrips = [], isLoading } = useGetTrips();
  const mainTrip = selectMainTrip(allTrips);

  // 활성화된 여행 정보 (React Query로 관리 - 캐시 무효화 시 자동 갱신)
  const { data: activeTrip } = useGetActiveTrip();
  const activatedTrip = activeTrip
    ? {
        tripId: activeTrip.tripId,
        status: (activeTrip.mapDownloaded ? 'ready' : 'preparing') as 'preparing' | 'ready',
      }
    : null;

  // TripData를 Trip 형태로 변환하는 함수
  const convertTripDataToTrip = (tripData: TripData, isMain: boolean = false): Trip => {
    const label = tripData.country ? `${tripData.destination}, ${tripData.country}` : tripData.destination;
    const isActivated = activatedTrip?.tripId === tripData.id;

    return {
      value: tripData.id.toString(),
      label,
      isMain,
      isActivated,
      activationStatus: isActivated ? activatedTrip?.status : undefined,
    };
  };

  // 여행 목록 생성 (메인 여행 표시 포함)
  const trips: Trip[] = allTrips.map((tripData) => convertTripDataToTrip(tripData, tripData.id === mainTrip?.id));

  // 선택된 여행 객체
  const selectedTrip = trips.find((trip) => trip.value === selectedTripId) || {
    value: '',
    label: '여행을 선택하세요',
  };

  const handleTripChange = (trip: Trip) => {
    setSelectedTripId(trip.value);
    setIsOpen(false);
  };

  // 로딩 중이거나 여행이 없을 때
  if (isLoading) {
    return (
      <View className={className}>
        <View className='flex-row items-center gap-xs px-md py-sm'>
          <Text className='text-body text-muted-foreground'>여행을 불러오는 중...</Text>
        </View>
      </View>
    );
  }

  if (trips.length === 0) {
    return (
      <View className={className}>
        <View className='w-full h-auto py-xs px-sm border border-border rounded-md'>
          <View className='w-full flex-row items-center'>
            <Plane size={18} color='hsl(0, 0%, 45%)' strokeWidth={2} />
            <Text className='text-body text-muted-foreground ml-xs'>여행이 없습니다</Text>
          </View>
        </View>
      </View>
    );
  }

  return (
    <>
      <View className={className}>
        <Pressable variant='outline' size='md' onPress={() => setIsOpen(true)} className='w-full h-auto py-xs px-sm'>
          <View className='w-full flex-row items-center justify-between'>
            <View className='flex-row items-center gap-xs'>
              <Plane size={18} color='hsl(0, 0%, 12%)' strokeWidth={2} />
              <Text className='text-body text-foreground'>{selectedTrip.label}</Text>
              {selectedTrip.isMain && (
                <Badge variant='secondary' className='ml-xs'>
                  <Text className='text-label-small text-muted-foreground'>메인</Text>
                </Badge>
              )}
              {selectedTrip.isActivated && (
                <Badge variant='default' className='ml-xs flex-row items-center gap-0.5 bg-emerald-100'>
                  <Text className='text-label-small text-emerald-700'>활성화</Text>
                </Badge>
              )}
            </View>
            <ChevronDown size={16} color='hsl(0, 0%, 45%)' strokeWidth={2} />
          </View>
        </Pressable>
      </View>

      <Drawer isOpen={isOpen} onClose={() => setIsOpen(false)} title='여행 선택'>
        <View className='flex-col gap-sm pb-xl'>
          {trips.map((trip) => {
            const isSelected = trip.value === selectedTrip.value;
            return (
              <Pressable
                key={trip.value}
                variant='ghost'
                size='lg'
                onPress={() => handleTripChange(trip)}
                className={`w-full h-auto py-sm px-md justify-start ${isSelected ? 'bg-muted' : ''}`}
              >
                <View className='w-full flex-row items-center'>
                  <View className='mr-sm items-center justify-center w-5'>
                    {isSelected ? (
                      <Check size={20} color='hsl(142, 76%, 36%)' strokeWidth={2.5} />
                    ) : (
                      <Plane size={20} color='hsl(0, 0%, 45%)' strokeWidth={2} />
                    )}
                  </View>
                  <View className='flex-1 flex-row items-center'>
                    <Text
                      className={`text-body-large ${isSelected ? 'font-medium text-foreground' : 'text-muted-foreground'}`}
                    >
                      {trip.label}
                    </Text>
                    {trip.isMain && (
                      <Badge variant='secondary' className='ml-sm'>
                        <Text className='text-label-small text-muted-foreground'>메인</Text>
                      </Badge>
                    )}
                    {trip.isActivated && (
                      <Badge variant='default' className='ml-xs flex-row items-center gap-0.5 bg-emerald-100'>
                        <Text className='text-label-small text-emerald-700'>활성화</Text>
                      </Badge>
                    )}
                  </View>
                </View>
              </Pressable>
            );
          })}
        </View>
      </Drawer>
    </>
  );
}

