import { View, Text } from 'react-native';
import { AlertCircle, WifiOff, Lock } from 'lucide-react-native';
import type { CRUDPermission } from '@/shared/policy/types';

type PolicyErrorDisplayProps = {
  permission: CRUDPermission;
  /**
   * 에러 표시 스타일
   * - banner: 상단 배너 (노란색, 경고)
   * - block: 화면 차단 (빨간색, 치명적)
   * - inline: 인라인 메시지 (컴포넌트 내부)
   */
  variant?: 'banner' | 'block' | 'inline';
  /**
   * 커스텀 메시지 (permission.reason 대신 사용)
   */
  message?: string;
};

/**
 * Policy 에러 표시 컴포넌트
 *
 * @example
 * ```tsx
 * const policy = useAppPolicy(tripId);
 *
 * if (!policy.schedule.create.allowed) {
 *   return <PolicyErrorDisplay permission={policy.schedule.create} variant="block" />;
 * }
 * ```
 */
export function PolicyErrorDisplay({ permission, variant = 'banner', message }: PolicyErrorDisplayProps) {
  const displayMessage = message || permission.reason || '이 작업을 수행할 수 없습니다';

  // 에러 아이콘 선택
  const getIcon = () => {
    if (permission.reason?.includes('오프라인')) {
      return <WifiOff size={20} color={variant === 'block' ? '#DC2626' : '#D97706'} />;
    }
    if (permission.reason?.includes('비활성')) {
      return <Lock size={20} color={variant === 'block' ? '#DC2626' : '#D97706'} />;
    }
    return <AlertCircle size={20} color={variant === 'block' ? '#DC2626' : '#D97706'} />;
  };

  // Banner 스타일 (경고)
  if (variant === 'banner') {
    return (
      <View className='bg-yellow-50 px-md py-sm border-b border-yellow-200 flex-row items-center'>
        {getIcon()}
        <Text className='text-small text-yellow-800 ml-xs flex-1'>{displayMessage}</Text>
      </View>
    );
  }

  // Block 스타일 (화면 차단)
  if (variant === 'block') {
    return (
      <View className='flex-1 items-center justify-center px-lg'>
        <View className='w-16 h-16 rounded-full bg-red-50 items-center justify-center mb-md'>{getIcon()}</View>
        <Text className='text-h3 text-foreground mb-sm text-center'>작업을 수행할 수 없습니다</Text>
        <Text className='text-body text-muted-foreground text-center'>{displayMessage}</Text>
      </View>
    );
  }

  // Inline 스타일 (컴포넌트 내부)
  return (
    <View className='bg-yellow-50 border border-yellow-200 rounded-md px-sm py-xs flex-row items-center'>
      {getIcon()}
      <Text className='text-small text-yellow-800 ml-xs flex-1'>{displayMessage}</Text>
    </View>
  );
}
import { View, Text, TouchableOpacity } from 'react-native';
import { Card, cn, Pressable } from '@repo/ui';
import { MapPin, Wallet, MoreVertical, AlertCircle } from 'lucide-react-native';
import { networkStore } from '@/shared/store/network';

interface ScheduleCardProps {
  date?: string;
  time: string;
  title: string;
  location: string;
  latitude?: string | null;
  expense?: string;
  expenseCount?: number;
  currency?: string;
  className?: string;
  onPress?: () => void;
  onMenuPress?: (event: any) => void;
}

export function ScheduleCard({
  date,
  time,
  title,
  location,
  latitude,
  expense,
  expenseCount,
  currency = 'USD',
  className,
  onPress,
  onMenuPress,
}: ScheduleCardProps) {
  // 온라인 상태 + 좌표 없음 → 경고 표시
  const showLocationWarning = networkStore.realStatus === 'online' && !latitude;

  return (
    <TouchableOpacity onPress={onPress} activeOpacity={0.95}>
      <Card className={cn('p-sm flex-col gap-xs relative', className)}>
        {/* Menu Button */}
        {onMenuPress && (
          <Pressable
            variant='ghost'
            className='absolute right-xs top-xs rounded-full p-2xs z-10'
            onPress={(event) => {
              event.stopPropagation();
              onMenuPress(event);
            }}
          >
            <MoreVertical size={20} color='#666' strokeWidth={2} />
          </Pressable>
        )}

        {/* Title */}
        <Text className='text-title-medium text-foreground pr-8'>{title}</Text>

        {/* Location */}
        <View className='flex-row items-center gap-3xs'>
          <MapPin size={14} color='hsl(120, 8%, 35%)' strokeWidth={2} />
          <Text className='text-body text-muted-foreground'>{location}</Text>
        </View>

        {/* 좌표 없음 경고 (온라인 상태 + 좌표 없음) */}
        {showLocationWarning && (
          <View className='bg-yellow-50 px-xs py-3xs rounded-md flex-row items-center gap-3xs'>
            <AlertCircle size={12} color='#D97706' />
            <Text className='text-small text-yellow-800'>좌표 없음 - 일정 수정에서 장소를 검색하세요</Text>
          </View>
        )}

        {/* Date, Time, and Expense */}
        <View className='flex-row items-center gap-xs'>
