export const networkStore = {
  get realStatus() {
    return useNetworkStore.getState().realStatus;
  },
  get override() {
    return useNetworkStore.getState().overrideStatus;
  },
  setOverride(status: NetworkStatus | null) {
    useNetworkStore.getState().setOverride(status);
  },
  init() {
    useNetworkStore.getState().init();
  },
  cleanup() {
    useNetworkStore.getState().cleanup();
  },
  refresh() {
    return useNetworkStore.getState().refresh();
  },
};

/** 화면 표시·제한 시뮬레이션용. 실제 요청 판단에는 사용하지 않는다. */
export function useDisplayNetworkStatus(): NetworkStatus {
  return useNetworkStore((state) => state.overrideStatus ?? state.realStatus);
}

export function useRealNetworkStatus(): NetworkStatus {
  return useNetworkStore((state) => state.realStatus);
}

export function useNetworkCheck() {
  const checkStatus = useNetworkStore((state) => state.checkStatus);
  const isRefreshing = useNetworkStore((state) => state.isRefreshing);
  const refresh = useNetworkStore((state) => state.refresh);

  return { checkStatus, isRefreshing, refresh };
}

export function useNetworkControl() {
  const overrideStatus = useNetworkStore((state) => state.overrideStatus);
  const setOverride = useNetworkStore((state) => state.setOverride);

  return {
    overrideStatus,
    setOverrideOnline: () => setOverride('online'),
    setOverrideOffline: () => setOverride('offline'),
    setOverrideUnknown: () => setOverride('unknown'),
    clearOverride: () => setOverride(null),
  };
}
import { useQuery } from '@tanstack/react-query';
import { db, tripActivations } from '@/shared/db';
import { eq, and } from 'drizzle-orm';
import { tripQueryKeys } from './keys';
import { authStore } from '@/shared/store/auth';

/**
 * 여행 활성화 상태 조회 Hook
 *
 * - tripActivations 테이블에서 활성화 정보 조회
 * - 활성화 여부, 동기화 상태, 만료 시간 등 제공
 *
 * @param tripId 여행 ID
 *
 * @example
 * ```tsx
 * const { data: activation, isLoading } = useGetTripActivation(tripId);
 * if (activation?.isActivated) {
 *   // 활성화된 여행
 * }
 * ```
 */
export const useGetTripActivation = (tripId: string) => {
  return useQuery({
    queryKey: tripQueryKeys.activation(tripId),
    queryFn: async () => {
      const activation = await db.select().from(tripActivations).where(eq(tripActivations.tripId, tripId)).get();

      if (!activation) {
        return null;
      }

      console.log(`📋 Trip activation loaded: ${tripId} (activated: ${activation.isActivated})`);
      return activation;
    },
    enabled: !!tripId,
    staleTime: 1 * 60 * 1000, // 1분
    gcTime: 5 * 60 * 1000, // 5분
  });
};

/**
 * 현재 사용자의 활성화된 여행 조회 Hook
 *
 * - 동시에 1개만 활성화 가능하므로, 현재 활성화된 여행 반환
 * - userId 필터링으로 다중 사용자 환경 지원
 *
 * @example
 * ```tsx
 * const { data: activeTrip } = useGetActiveTrip();
 * ```
 */
export const useGetActiveTrip = () => {
  return useQuery({
    queryKey: tripQueryKeys.activeTrip(),
    queryFn: async () => {
      const userId = authStore.userId;

      // 인증되지 않은 상태면 null 반환
      if (!userId) {
        console.log(`📋 [useGetActiveTrip] No authenticated user`);
        return null;
      }

      const activation = await db
        .select()
        .from(tripActivations)
        .where(and(eq(tripActivations.isActivated, true), eq(tripActivations.userId, userId)))
        .get();

      if (!activation) {
        console.log(`📋 No active trip found for user ${userId}`);
        return null;
      }

      console.log(`📋 Active trip loaded: ${activation.tripId} for user ${userId}`);
      return activation;
    },
    staleTime: 1 * 60 * 1000, // 1분
    gcTime: 5 * 60 * 1000, // 5분
  });
};
