import { useState } from 'react';
import { View, Text } from 'react-native';
import { Plane, ChevronDown, Check, WifiOff } from 'lucide-react-native';
import { Badge, Drawer, Pressable } from '@repo/ui';
import { useGetTrips } from '../data';
import { useGetActiveTrip } from '../data/useGetTripActivation';
import { selectMainTrip } from '../utils';
import { useTripStore } from '@/shared/store';
import type { TripData } from '../model';

interface Trip {
  value: string;
  label: string;
  isMain?: boolean;
  isActivated?: boolean;
  activationStatus?: 'preparing' | 'ready';
}

interface TripSelectorProps {
  className?: string;
}

/**
 * TripSelector - 현재 여행 선택 컴포넌트
 *
 * packages/ui의 Select Compound Component를 조합하여 만든
 * 여행 선택 특화 컴포넌트입니다.
 *
 * 실제 여행 데이터를 API에서 가져와서 표시하며,
 * 메인 여행은 자동으로 식별되어 뱃지로 표시됩니다.
 * 일정, 경비 등 화면 상단에 sticky 형태로 배치되어
 * 현재 선택된 여행을 표시하고 변경할 수 있습니다.
 *
 * @example
 * <TripSelector
 *   onTripChange={(trip) => console.log('Selected:', trip)}
 * />
 */
export function TripSelector({ className = '' }: TripSelectorProps) {
  // ✨ Zustand 전역 상태
  const { selectedTripId, setSelectedTripId } = useTripStore();
  const [isOpen, setIsOpen] = useState(false);

  // 실제 여행 데이터 가져오기
  const { data: allTrips = [], isLoading } = useGetTrips();
  const mainTrip = selectMainTrip(allTrips);

  // 활성화된 여행 정보 (React Query로 관리 - 캐시 무효화 시 자동 갱신)
  const { data: activeTrip } = useGetActiveTrip();
  const activatedTrip = activeTrip
    ? {
        tripId: activeTrip.tripId,
        status: (activeTrip.mapDownloaded ? 'ready' : 'preparing') as 'preparing' | 'ready',
      }
    : null;

  // TripData를 Trip 형태로 변환하는 함수
  const convertTripDataToTrip = (tripData: TripData, isMain: boolean = false): Trip => {
    const label = tripData.country ? `${tripData.destination}, ${tripData.country}` : tripData.destination;
    const isActivated = activatedTrip?.tripId === tripData.id;

    return {
      value: tripData.id.toString(),
      label,
      isMain,
      isActivated,
      activationStatus: isActivated ? activatedTrip?.status : undefined,
    };
  };

  // 여행 목록 생성 (메인 여행 표시 포함)
  const trips: Trip[] = allTrips.map((tripData) => convertTripDataToTrip(tripData, tripData.id === mainTrip?.id));

  // 선택된 여행 객체
  const selectedTrip = trips.find((trip) => trip.value === selectedTripId) || {
    value: '',
    label: '여행을 선택하세요',
  };

  const handleTripChange = (trip: Trip) => {
    setSelectedTripId(trip.value);
    setIsOpen(false);
  };

  // 로딩 중이거나 여행이 없을 때
  if (isLoading) {
    return (
      <View className={className}>
        <View className='flex-row items-center gap-xs px-md py-sm'>
          <Text className='text-body text-muted-foreground'>여행을 불러오는 중...</Text>
        </View>
      </View>
    );
  }

  if (trips.length === 0) {
    return (
      <View className={className}>
        <View className='w-full h-auto py-xs px-sm border border-border rounded-md'>
          <View className='w-full flex-row items-center'>
            <Plane size={18} color='hsl(0, 0%, 45%)' strokeWidth={2} />
            <Text className='text-body text-muted-foreground ml-xs'>여행이 없습니다</Text>
          </View>
        </View>
      </View>
    );
  }

  return (
    <>
      <View className={className}>
        <Pressable variant='outline' size='md' onPress={() => setIsOpen(true)} className='w-full h-auto py-xs px-sm'>
          <View className='w-full flex-row items-center justify-between'>
            <View className='flex-row items-center gap-xs'>
              <Plane size={18} color='hsl(0, 0%, 12%)' strokeWidth={2} />
              <Text className='text-body text-foreground'>{selectedTrip.label}</Text>
              {selectedTrip.isMain && (
                <Badge variant='secondary' className='ml-xs'>
                  <Text className='text-label-small text-muted-foreground'>메인</Text>
                </Badge>
              )}
              {selectedTrip.isActivated && (
                <Badge variant='default' className='ml-xs flex-row items-center gap-0.5 bg-emerald-100'>
                  <Text className='text-label-small text-emerald-700'>활성화</Text>
                </Badge>
              )}
            </View>
            <ChevronDown size={16} color='hsl(0, 0%, 45%)' strokeWidth={2} />
          </View>
        </Pressable>
      </View>

      <Drawer isOpen={isOpen} onClose={() => setIsOpen(false)} title='여행 선택'>
        <View className='flex-col gap-sm pb-xl'>
          {trips.map((trip) => {
            const isSelected = trip.value === selectedTrip.value;
            return (
              <Pressable
                key={trip.value}
                variant='ghost'
                size='lg'
                onPress={() => handleTripChange(trip)}
                className={`w-full h-auto py-sm px-md justify-start ${isSelected ? 'bg-muted' : ''}`}
              >
                <View className='w-full flex-row items-center'>
                  <View className='mr-sm items-center justify-center w-5'>
                    {isSelected ? (
                      <Check size={20} color='hsl(142, 76%, 36%)' strokeWidth={2.5} />
                    ) : (
                      <Plane size={20} color='hsl(0, 0%, 45%)' strokeWidth={2} />
                    )}
                  </View>
                  <View className='flex-1 flex-row items-center'>
                    <Text
                      className={`text-body-large ${isSelected ? 'font-medium text-foreground' : 'text-muted-foreground'}`}
                    >
                      {trip.label}
                    </Text>
                    {trip.isMain && (
                      <Badge variant='secondary' className='ml-sm'>
                        <Text className='text-label-small text-muted-foreground'>메인</Text>
                      </Badge>
                    )}
                    {trip.isActivated && (
                      <Badge variant='default' className='ml-xs flex-row items-center gap-0.5 bg-emerald-100'>
                        <Text className='text-label-small text-emerald-700'>활성화</Text>
                      </Badge>
                    )}
                  </View>
                </View>
              </Pressable>
            );
          })}
        </View>
      </Drawer>
    </>
  );
}
import { useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, Alert } from 'react-native';
import { Controller, useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Calendar, Clock, MapPin } from 'lucide-react-native';
import { Drawer, Pressable } from '@repo/ui';
import { DatePicker, TimePicker } from '@/shared/components';
import { Field } from '@/shared/components/Form';
import { useUpdateSchedule, useGetSchedules, type Schedule } from '@/entities/schedule';
import { useAutoDownloadRoutes } from '@/entities/route';
import { useAppPolicy } from '@/shared/policy';
import { scheduleUpdateFormSchema, type ScheduleUpdateFormData } from './schema';
import { combineDateTimeToISO } from '@/shared/lib/datetime';
import { LocationSearchModal } from './LocationSearchModal';
import type { Location } from '@/features/schedule/create-schedule';

export type UpdateScheduleDrawerProps = {
  isOpen: boolean;
  onClose: () => void;
  scheduleData?: {
    id: string;
    tripId: string;
    title: string;
    date: string;
    time: string;
    location?: string;
    address?: string | null;
    latitude?: string | null;
    longitude?: string | null;
  } | null;
};

/**
 * 일정 수정 드로어 컴포넌트
 * 제목, 날짜와 시간을 수정할 수 있는 UI
 */
export const UpdateScheduleDrawer = ({ isOpen, onClose, scheduleData }: UpdateScheduleDrawerProps) => {
  // react-hook-form 설정
  const { control, handleSubmit, setValue } = useForm<ScheduleUpdateFormData>({
    resolver: zodResolver(scheduleUpdateFormSchema),
    defaultValues: {
      title: scheduleData?.title || '',
      date: scheduleData?.date || '',
      time: scheduleData?.time || '',
    },
    mode: 'onChange',
  });

  // Picker visibility state
  const [datePickerVisible, setDatePickerVisible] = useState(false);
  const [timePickerVisible, setTimePickerVisible] = useState(false);
  const [locationSearchVisible, setLocationSearchVisible] = useState(false);

  // 선택된 장소 (재검색 시)
  const [selectedLocation, setSelectedLocation] = useState<Location | null>(null);

  // Mutations and queries
  const { mutate: updateSchedule, isPending } = useUpdateSchedule();
  const { mutate: autoDownloadRoutes } = useAutoDownloadRoutes();
  const { data: schedules = [] } = useGetSchedules(scheduleData?.tripId || '');

  // Policy 체크
  const policy = useAppPolicy(scheduleData?.tripId);

  // scheduleData가 변경되면 폼 값 및 상태 초기화
  useEffect(() => {
    if (scheduleData) {
      setValue('title', scheduleData.title);
      setValue('date', scheduleData.date);
      setValue('time', scheduleData.time);
      setSelectedLocation(null); // 장소 재검색 결과 초기화
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scheduleData?.id]);

  // Handlers
  const handleDateSelect = (selectedDate: string) => {
    setValue('date', selectedDate, { shouldValidate: true });
    setDatePickerVisible(false);
  };

  const handleTimeSelect = (selectedTime: string) => {
    setValue('time', selectedTime, { shouldValidate: true });
    setTimePickerVisible(false);
  };

  const handleLocationSelect = (location: Location) => {
    setSelectedLocation(location);
    setLocationSearchVisible(false);
  };

  // 저장 핸들러 (유효성 검사는 zodResolver가 처리)
  const onValid = (data: ScheduleUpdateFormData) => {
    if (!scheduleData) return;

    // ✅ TIME_ARCHITECTURE_GUIDE: UI → Logic 변환
    // "2024-03-15" + "14:30" → "2024-03-15T14:30:00.000Z"
    const scheduledAt = combineDateTimeToISO(data.date, data.time);

    // 장소 재검색한 경우 location 정보 추가
    const locationData = selectedLocation
      ? {
          location: selectedLocation.name,
          address: selectedLocation.address,
          latitude: selectedLocation.latitude,
          longitude: selectedLocation.longitude,
        }
      : {};

    updateSchedule(
      {
        id: scheduleData.id,
        data: {
          title: data.title,
          scheduledAt, // ISO 8601 format
          ...locationData,
        },
      },
      {
        onSuccess: () => {
          Alert.alert('성공', '일정이 수정되었습니다.');

          // 경로 재다운로드 (날짜/시간 변경으로 순서가 바뀔 수 있음)
          setTimeout(() => {
            const allSchedules = schedules
              .map((s: Schedule) => ({
                id: s.id,
                latitude: s.latitude ? parseFloat(s.latitude) : undefined,
                longitude: s.longitude ? parseFloat(s.longitude) : undefined,
                scheduledAt: s.id === scheduleData.id ? scheduledAt : s.scheduledAt,
              }))
              .sort(
                (a: { scheduledAt: string }, b: { scheduledAt: string }) =>
                  new Date(a.scheduledAt).getTime() - new Date(b.scheduledAt).getTime(),
              )
              .map(
                ({
                  id: scheduleId,
                  latitude,
                  longitude,
                }: {
                  id: string;
                  latitude: number | undefined;
                  longitude: number | undefined;
                }) => ({ id: scheduleId, latitude, longitude }),
              );

            autoDownloadRoutes({ tripId: scheduleData.tripId, schedules: allSchedules });
          }, 500);

          onClose();
        },
        onError: () => {
          Alert.alert('오류', '일정 수정에 실패했습니다.');
        },
      },
    );
  };

  const onInvalid = () => {
    Alert.alert('오류', '입력한 정보를 확인해주세요.');
  };

  if (!scheduleData) return null;

  return (
    <Drawer isOpen={isOpen} onClose={onClose} title='일정 수정'>
      <View className='gap-md'>
        {/* 설명 */}
        <Text className='text-body text-muted-foreground'>{scheduleData.title}의 날짜와 시간을 수정합니다</Text>

        {/* 제목 필드 */}
        <Controller
          control={control}
          name='title'
          render={({ field: { value, onChange }, fieldState: { error } }) => (
            <Field>
              <Field.Title>제목</Field.Title>
              <Field.ElementsBox>
                <TouchableOpacity
                  className='h-11 rounded-md border border-input bg-background px-sm justify-center'
                  onPress={() => {
                    // TextInput으로 변경하거나 모달로 수정
                    Alert.prompt('제목 수정', '새로운 제목을 입력하세요', [
                      { text: '취소', style: 'cancel' },
                      {
                        text: '확인',
                        onPress: (text) => {
                          if (text) onChange(text);
                        },
                      },
                    ]);
                  }}
                >
                  <Text className='text-body text-foreground'>{value || '제목을 입력하세요'}</Text>
                </TouchableOpacity>
              </Field.ElementsBox>
              {error && <Field.Message>{error.message}</Field.Message>}
            </Field>
          )}
        />

        {/* 날짜 필드 */}
        <Controller
          control={control}
          name='date'
          render={({ field: { value }, fieldState: { error } }) => (
            <Field>
              <Field.Title>날짜</Field.Title>
              <Field.ElementsBox>
                <TouchableOpacity
                  className='h-11 flex-row items-center rounded-md border border-input bg-background px-sm'
                  onPress={() => setDatePickerVisible(true)}
                >
                  <Calendar size={16} color='#808080' />
                  <Text className='text-body text-foreground ml-xs'>{value}</Text>
                </TouchableOpacity>
              </Field.ElementsBox>
              {error && <Field.Message>{error.message}</Field.Message>}
            </Field>
          )}
        />

        {/* 시간 필드 */}
        <Controller
          control={control}
          name='time'
          render={({ field: { value }, fieldState: { error } }) => (
            <Field>
              <Field.Title>시간</Field.Title>
              <Field.ElementsBox>
                <TouchableOpacity
                  className='h-11 flex-row items-center rounded-md border border-input bg-background px-sm'
                  onPress={() => setTimePickerVisible(true)}
                >
                  <Clock size={16} color='#808080' />
                  <Text className='text-body text-foreground ml-xs'>{value}</Text>
                </TouchableOpacity>
              </Field.ElementsBox>
              {error && <Field.Message>{error.message}</Field.Message>}
            </Field>
          )}
        />

        {/* 장소 재검색 (좌표 없을 때만 표시) */}
        {!scheduleData.latitude && scheduleData.location && (
          <View className='bg-yellow-50 px-sm py-sm rounded-md border border-yellow-200'>
            <View className='flex-row items-center justify-between'>
              <View className='flex-1'>
                <Text className='text-small font-medium text-yellow-800 mb-3xs'>⚠️ 좌표가 없습니다</Text>
                <Text className='text-small text-yellow-700'>{scheduleData.location}</Text>
              </View>
              {policy.service.searchMode === 'api' && (
                <TouchableOpacity
                  className='ml-sm px-sm py-xs rounded-md bg-yellow-200'
                  onPress={() => setLocationSearchVisible(true)}
                >
                  <View className='flex-row items-center gap-xs'>
                    <MapPin size={14} color='#D97706' />
                    <Text className='text-small font-medium text-yellow-800'>검색</Text>
                  </View>
                </TouchableOpacity>
              )}
            </View>
          </View>
        )}

        {/* 장소 재검색 결과 (선택한 경우) */}
        {selectedLocation && (
          <View className='bg-green-50 px-sm py-sm rounded-md border border-green-200'>
            <View className='flex-row items-center'>
              <MapPin size={16} color='#22C55E' />
              <View className='flex-1 ml-xs'>
                <Text className='text-small font-medium text-green-800'>{selectedLocation.name}</Text>
                <Text className='text-small text-green-600'>{selectedLocation.address}</Text>
              </View>
            </View>
          </View>
        )}

        {/* 버튼 영역 */}
        <View className='flex-row gap-sm mt-md'>
          <View className='flex-1'>
            <Pressable variant='default' onPress={handleSubmit(onValid, onInvalid)} disabled={isPending}>
              {isPending ? '저장 중...' : '저장'}
            </Pressable>
          </View>
          <View className='flex-1'>
            <Pressable variant='outline' onPress={onClose} disabled={isPending}>
              취소
            </Pressable>
          </View>
        </View>
      </View>

      {/* DatePicker Modal */}
      {datePickerVisible && (
        <DatePicker
          visible={datePickerVisible}
          onClose={() => setDatePickerVisible(false)}
          onSelectDate={handleDateSelect}
        />
      )}

      {/* TimePicker Modal */}
      {timePickerVisible && (
        <TimePicker
          visible={timePickerVisible}
          onClose={() => setTimePickerVisible(false)}
          onSelectTime={handleTimeSelect}
          initialTime={scheduleData.time}
        />
      )}

      {/* LocationSearch Modal */}
      {locationSearchVisible && scheduleData && (
        <LocationSearchModal
          isOpen={locationSearchVisible}
          onClose={() => setLocationSearchVisible(false)}
          onSelectLocation={handleLocationSelect}
          tripId={scheduleData.tripId}
          initialQuery={scheduleData.location || ''}
        />
      )}
    </Drawer>
  );
};
import { useEffect, useState, useMemo } from 'react';
import { View, Text, TextInput, Alert, TouchableOpacity, ScrollView } from 'react-native';
import { Controller, useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Wallet, ChevronDown, Calendar as CalendarIcon, MapPin } from 'lucide-react-native';
import { Drawer, Pressable, Select } from '@repo/ui';
import { DatePicker } from '@/shared/components';
import { Field } from '@/shared/components/Form';
import { EXPENSE_CATEGORIES, CURRENCIES, CURRENCY_SYMBOLS } from '@/entities/expense';
import { useUpdateExpense } from '@/entities/expense/data/useUpdateExpense';
import { formatISOToLocalDate, formatISOToLocalTime, dateToISODateTime } from '@/shared/lib/datetime';
import { useGetSchedules } from '@/entities/schedule';
import { expenseUpdateFormSchema, type ExpenseUpdateFormData } from './schema';

export type UpdateExpenseDrawerProps = {
  isOpen: boolean;
  onClose: () => void;
  expenseData?: {
    id: string;
    title: string;
    amount: string;
    currency: string;
    category: string;
    date: string; // ISO datetime string
    scheduleId?: string;
    tripId: string;
  } | null;
};

/**
 * 경비 수정 드로어 컴포넌트
 * 제목, 금액, 통화, 카테고리, 날짜, 연결된 일정을 수정할 수 있는 UI
 */
export const UpdateExpenseDrawer = ({ isOpen, onClose, expenseData }: UpdateExpenseDrawerProps) => {
  // react-hook-form 설정
  const { control, handleSubmit, setValue, watch } = useForm<ExpenseUpdateFormData>({
    resolver: zodResolver(expenseUpdateFormSchema),
    defaultValues: {
      title: expenseData?.title || '',
      amount: expenseData?.amount || '',
      currency: expenseData?.currency || 'USD',
      category: expenseData?.category || '',
      date: expenseData?.date || '',
      scheduleId: expenseData?.scheduleId || undefined,
    },
    mode: 'onChange',
  });

  // Picker visibility state
  const [isDatePickerOpen, setIsDatePickerOpen] = useState(false);

  // useUpdateExpense mutation hook
  const { mutate: updateExpense, isPending } = useUpdateExpense();

  // 선택한 날짜 추적
  const selectedDate = watch('date');

  // 여행의 모든 일정 조회
  const { data: schedules = [] } = useGetSchedules(expenseData?.tripId || '');

  // 선택한 날짜의 일정만 필터링
  const schedulesOnSelectedDate = useMemo(() => {
    if (!selectedDate) return [];

    const selectedLocalDate = formatISOToLocalDate(selectedDate);

    return schedules.filter((schedule) => {
      const scheduleDate = formatISOToLocalDate(schedule.scheduledAt);
      return scheduleDate === selectedLocalDate;
    });
  }, [selectedDate, schedules]);

  // expenseData가 변경되면 폼 값 업데이트
  useEffect(() => {
    if (expenseData) {
      setValue('title', expenseData.title);
      setValue('amount', expenseData.amount);
      setValue('currency', expenseData.currency);
      setValue('category', expenseData.category);
      setValue('date', expenseData.date);
      setValue('scheduleId', expenseData.scheduleId || undefined);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expenseData?.id]);

  // 저장 핸들러 (유효성 검사는 zodResolver가 처리)
  const onValid = (data: ExpenseUpdateFormData) => {
    if (!expenseData) return;

    // ✅ Selective Local-First: 로컬 DB 업데이트 + sync_queue 기록
    updateExpense(
      {
        id: expenseData.id,
        data: {
          title: data.title,
          amount: data.amount,
          currency: data.currency,
          category: data.category,
          date: data.date,
          scheduleId: data.scheduleId || null,
        },
      },
      {
        onSuccess: () => {
          Alert.alert('성공', '경비가 수정되었습니다.');
          onClose();
        },
        onError: () => {
          Alert.alert('오류', '경비 수정에 실패했습니다.');
        },
      },
    );
  };

  const onInvalid = () => {
    Alert.alert('오류', '입력한 정보를 확인해주세요.');
  };

  if (!expenseData) return null;

  return (
    <Drawer isOpen={isOpen} onClose={onClose} title='경비 수정'>
      <ScrollView showsVerticalScrollIndicator={false}>
        <View className='gap-md'>
          {/* 설명 */}
          <Text className='text-body text-muted-foreground'>{expenseData.title}의 정보를 수정합니다</Text>

          {/* 제목 */}
          <Controller
            control={control}
            name='title'
            render={({ field: { value, onChange }, fieldState: { error } }) => (
              <Field>
                <Field.Title>제목 *</Field.Title>
                <Field.ElementsBox>
                  <TouchableOpacity
                    className='h-11 rounded-md border border-input bg-background px-sm justify-center'
                    onPress={() => {
                      Alert.prompt('제목 수정', '새로운 제목을 입력하세요', [
                        { text: '취소', style: 'cancel' },
                        {
                          text: '확인',
                          onPress: (text) => {
                            if (text) onChange(text);
                          },
                        },
                      ]);
                    }}
                  >
                    <Text className='text-body text-foreground'>{value || '제목을 입력하세요'}</Text>
                  </TouchableOpacity>
                </Field.ElementsBox>
                {error && <Field.Message>{error.message}</Field.Message>}
              </Field>
            )}
          />

          {/* 금액 */}
          <Controller
            control={control}
            name='amount'
            render={({ field: { value, onChange }, fieldState: { error } }) => (
              <Field>
                <Field.Title>금액 *</Field.Title>
                <Field.ElementsBox>
                  <TouchableOpacity
                    className='h-11 rounded-md border border-input bg-background px-sm justify-center'
                    onPress={() => {
                      Alert.prompt(
                        '금액 수정',
                        '새로운 금액을 입력하세요',
                        [
                          { text: '취소', style: 'cancel' },
                          {
                            text: '확인',
                            onPress: (text) => {
                              if (text) onChange(text);
                            },
                          },
                        ],
                        'plain-text',
                        value,
                        'decimal-pad',
                      );
                    }}
                  >
                    <Text className='text-body text-foreground'>{value || '0.00'}</Text>
                  </TouchableOpacity>
                </Field.ElementsBox>
                {error && <Field.Message>{error.message}</Field.Message>}
              </Field>
            )}
          />

          {/* 통화 */}
          <Controller
            control={control}
            name='currency'
            render={({ field: { value, onChange }, fieldState: { error } }) => (
              <Field>
                <Field.Title>통화 *</Field.Title>
                <Field.ElementsBox>
                  <Select
                    value={{
                      value,
                      label: `${value} (${CURRENCY_SYMBOLS[value as keyof typeof CURRENCY_SYMBOLS] || ''})`,
                    }}
                    onValueChange={(option) => option && onChange(option.value)}
                  >
                    <Select.Trigger>
                      <View className='flex-row items-center gap-xs flex-1'>
                        <Wallet size={16} color='hsl(0, 0%, 45%)' />
                        <Select.Value placeholder='통화 선택' />
                      </View>
                      <ChevronDown size={16} color='hsl(0, 0%, 45%)' />
                    </Select.Trigger>

                    <Select.Portal>
                      <Select.Overlay>
                        <Select.Content>
                          <Select.Viewport>
                            {CURRENCIES.map((currency) => (
                              <Select.Item
                                key={currency}
                                value={currency}
                                label={`${currency} (${CURRENCY_SYMBOLS[currency]})`}
                              >
                                <Select.ItemText>
                                  {currency} ({CURRENCY_SYMBOLS[currency]})
                                </Select.ItemText>
                              </Select.Item>
                            ))}
                          </Select.Viewport>
                        </Select.Content>
                      </Select.Overlay>
                    </Select.Portal>
                  </Select>
                </Field.ElementsBox>
                {error && <Field.Message>{error.message}</Field.Message>}
              </Field>
            )}
          />

          {/* 카테고리 */}
          <Controller
            control={control}
            name='category'
            render={({ field: { value, onChange }, fieldState: { error } }) => (
              <Field>
                <Field.Title>카테고리 *</Field.Title>
                <Field.ElementsBox>
                  <Select
                    value={value ? { value, label: value } : undefined}
                    onValueChange={(option) => option && onChange(option.value)}
                  >
                    <Select.Trigger>
                      <Select.Value placeholder='카테고리 선택' />
                      <ChevronDown size={16} color='hsl(0, 0%, 45%)' />
                    </Select.Trigger>

                    <Select.Portal>
                      <Select.Overlay>
                        <Select.Content>
                          <Select.Viewport>
                            {EXPENSE_CATEGORIES.map((category) => (
                              <Select.Item key={category} value={category} label={category}>
                                <Select.ItemText>{category}</Select.ItemText>
                              </Select.Item>
                            ))}
                          </Select.Viewport>
                        </Select.Content>
                      </Select.Overlay>
                    </Select.Portal>
                  </Select>
                </Field.ElementsBox>
                {error && <Field.Message>{error.message}</Field.Message>}
              </Field>
            )}
          />

          {/* 날짜 */}
          <Controller
            control={control}
            name='date'
            render={({ field: { value, onChange }, fieldState: { error } }) => {
              // ✅ TIME_ARCHITECTURE_GUIDE: ISO → Local Date for display
              const displayDate = value ? formatISOToLocalDate(value) : '날짜 선택';

              return (
                <Field>
                  <Field.Title>날짜 *</Field.Title>
                  <Field.ElementsBox>
                    <TouchableOpacity
                      className='h-11 flex-row items-center rounded-md border border-input bg-background px-sm'
                      onPress={() => setIsDatePickerOpen(true)}
                    >
                      <CalendarIcon size={16} color='#808080' />
                      <Text className='text-body text-foreground ml-xs'>{displayDate}</Text>
                    </TouchableOpacity>
                  </Field.ElementsBox>
                  {error && <Field.Message>{error.message}</Field.Message>}

                  {/* DatePicker Modal */}
                  <DatePicker
                    visible={isDatePickerOpen}
                    onClose={() => setIsDatePickerOpen(false)}
                    onSelectDate={(dateString) => {
                      // ✅ TIME_ARCHITECTURE_GUIDE: Date → ISO datetime
                      // "2024-03-15" → "2024-03-15T00:00:00.000Z"
                      onChange(dateToISODateTime(dateString));
                      setIsDatePickerOpen(false);
                    }}
                    markedDates={{
                      [displayDate]: {
                        selected: true,
                        selectedColor: 'hsl(120, 61%, 34%)',
                      },
                    }}
                  />
                </Field>
              );
            }}
          />

          {/* 연결된 일정 (선택) */}
          <Controller
            control={control}
            name='scheduleId'
            render={({ field: { value, onChange }, fieldState: { error } }) => {
              const selectedSchedule = schedulesOnSelectedDate.find((s) => s.id === value);

              return (
                <Field>
                  <Field.Title>연결된 일정 (선택)</Field.Title>
                  <Field.ElementsBox>
                    <Select
                      value={
                        selectedSchedule
                          ? {
                              value: selectedSchedule.id,
                              label: `${formatISOToLocalTime(selectedSchedule.scheduledAt)} ${selectedSchedule.title}`,
                            }
                          : undefined
                      }
                      onValueChange={(option) => onChange(option?.value || undefined)}
                    >
                      <Select.Trigger>
                        <View className='flex-row items-center gap-xs flex-1'>
                          <MapPin size={16} color='hsl(0, 0%, 45%)' />
                          <Select.Value placeholder='일정 선택 (선택사항)' />
                        </View>
                        <ChevronDown size={16} color='hsl(0, 0%, 45%)' />
                      </Select.Trigger>

                      <Select.Portal>
                        <Select.Overlay>
                          <Select.Content>
                            <Select.Viewport>
                              {schedulesOnSelectedDate.length === 0 ? (
                                <View className='px-md py-lg'>
                                  <Text className='text-body text-center text-muted-foreground'>
                                    {selectedDate ? '이 날의 일정이 없습니다' : '먼저 날짜를 선택해주세요'}
                                  </Text>
                                </View>
                              ) : (
