          />
        </View>

        <Pressable variant='default' onPress={handleSubmit(onValid, onInvalid)} disabled={isPending || !isOnline}>
          {isPending ? '생성 중...' : '여행 생성'}
        </Pressable>

        {/* 오프라인 안내 */}
        {!isOnline && (
          <View className='mt-xs px-xs'>
            <Text className='text-small text-center text-muted-foreground'>인터넷 연결이 필요합니다</Text>
          </View>
        )}
      </View>
      <DatePicker
        visible={pickerVisible}
        onClose={() => setPickerVisible(false)}
        onSelectDate={handleSelectDate}
        minDate={currentPicker === 'end' && startDate ? startDate : undefined}
      />
    </>
  );
}
import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useCreateSchedule, useGetSchedules, type Schedule } from '@/entities/schedule';
import { useAutoDownloadRoutes } from '@/entities/route';
import { createScheduleFormSchema, type CreateScheduleFormData } from './schema';
import { combineDateTimeToISO } from '@/shared/lib/datetime';
import { generateId } from '@/shared/services/id/ulid';
import type { Location } from './types';

type UseCreateScheduleFormProps = {
  tripId: string;
  selectedLocation: Location | null;
  onSuccess?: () => void;
};

export const useCreateScheduleForm = ({ tripId, selectedLocation, onSuccess }: UseCreateScheduleFormProps) => {
  const [datePickerVisible, setDatePickerVisible] = useState(false);
  const [timePickerVisible, setTimePickerVisible] = useState(false);

  const form = useForm<CreateScheduleFormData>({
    resolver: zodResolver(createScheduleFormSchema),
    defaultValues: {
      title: '',
      location: '',
      address: '',
      date: '',
      time: '09:00',
    },
    mode: 'onChange',
  });

  // 장소 선택 시 폼 값 자동 설정
  useEffect(() => {
    if (selectedLocation) {
      form.setValue('title', selectedLocation.name);
      form.setValue('location', selectedLocation.name);
      form.setValue('address', selectedLocation.address);
    }
  }, [selectedLocation, form]);

  const { mutate: createSchedule, isPending } = useCreateSchedule();
  const { mutate: autoDownloadRoutes } = useAutoDownloadRoutes();
  const { data: schedules = [] } = useGetSchedules(tripId);

  const handleShowDatePicker = () => {
    setDatePickerVisible(true);
  };

  const handleShowTimePicker = () => {
    setTimePickerVisible(true);
  };

  const handleSelectDate = (date: string) => {
    form.setValue('date', date, { shouldValidate: true });
    setDatePickerVisible(false);
  };

  const handleSelectTime = (time: string) => {
    form.setValue('time', time, { shouldValidate: true });
    setTimePickerVisible(false);
  };

  const onValid = (data: CreateScheduleFormData) => {
    // ✅ Client-Side ID: Generate ULID on client
    const id = generateId();

    // ✅ date + time → ISO string with timezone
    const scheduledAt = combineDateTimeToISO(data.date, data.time);

    createSchedule(
      {
        id, // ✅ Client-Side ID
        tripId,
        title: data.title,
        location: data.location,
        address: data.address || selectedLocation?.address || null,
        scheduledAt, // ISO string
        latitude: selectedLocation?.latitude || null,
        longitude: selectedLocation?.longitude || null,
      },
      {
        onSuccess: () => {
          console.log('✅ Schedule created successfully');

          // 경로 자동 다운로드 (새 일정 포함)
          setTimeout(() => {
            const newSchedule = {
              id,
              latitude: selectedLocation?.latitude ? parseFloat(String(selectedLocation.latitude)) : undefined,
              longitude: selectedLocation?.longitude ? parseFloat(String(selectedLocation.longitude)) : undefined,
            };

            // scheduledAt 기준으로 정렬된 전체 일정 목록
            const allSchedules = [
              ...schedules.map((s: Schedule) => ({
                id: s.id,
                latitude: s.latitude ? parseFloat(s.latitude) : undefined,
                longitude: s.longitude ? parseFloat(s.longitude) : undefined,
                scheduledAt: s.scheduledAt,
              })),
              {
                ...newSchedule,
                scheduledAt,
              },
            ]
              .sort((a, b) => new Date(a.scheduledAt).getTime() - new Date(b.scheduledAt).getTime())
              .map(({ id: scheduleId, latitude, longitude }) => ({ id: scheduleId, latitude, longitude }));

            autoDownloadRoutes({ tripId, schedules: allSchedules });
          }, 500);

          form.reset();
          onSuccess?.();
        },
      },
    );
  };

  const onInvalid = () => {
    console.log('Form validation failed');
  };

  return {
    form,
    isPending,
    datePickerVisible,
    timePickerVisible,
    handleShowDatePicker,
    handleShowTimePicker,
    handleSelectDate,
    handleSelectTime,
    onSubmit: form.handleSubmit(onValid, onInvalid),
  };
};
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useRouter } from 'expo-router';
import { useCreateExpense } from '@/entities/expense';
import { useGetTrips } from '@/entities/trip';
import { generateId } from '@/shared/services/id/ulid';
import { dateToISODateTime } from '@/shared/lib/datetime';
import { createExpenseFormSchema, type CreateExpenseFormData } from './schema';

interface UseCreateExpenseFormProps {
  tripId: string;
  date?: string; // 경비 날짜 (YYYY-MM-DD 또는 ISO datetime)
  scheduleId?: string;
  onSuccess?: () => void;
}

export const useCreateExpenseForm = ({ tripId, date, scheduleId, onSuccess }: UseCreateExpenseFormProps) => {
  const router = useRouter();

  // ✅ CURRENCY_POLICY: 여행의 baseCurrency를 경비 기본 통화로 사용
  const { data: trips = [] } = useGetTrips();
  const selectedTrip = trips.find((trip) => trip.id === tripId);
  const defaultCurrency = selectedTrip?.baseCurrency || 'USD';

  // ✅ TIME_ARCHITECTURE_GUIDE Pattern 2: Date → ISO datetime
  // "2024-03-15" → "2024-03-15T00:00:00.000Z"
  const defaultDate = date ? dateToISODateTime(date) : dateToISODateTime(new Date().toISOString().split('T')[0]);

  const form = useForm<CreateExpenseFormData>({
    resolver: zodResolver(createExpenseFormSchema),
    defaultValues: {
      title: '',
      amount: '',
      currency: defaultCurrency, // ✅ 여행의 기본 통화 사용
      category: '',
      date: defaultDate, // ✅ ISO datetime string
      scheduleId: scheduleId || undefined,
    },
    mode: 'onChange',
  });

  const { mutate: createExpense, isPending } = useCreateExpense();

  const onValid = (data: CreateExpenseFormData) => {
    createExpense(
      {
        id: generateId(), // ✅ 외부에서 ID 생성
        tripId,
        title: data.title,
        amount: data.amount,
        currency: data.currency,
        category: data.category,
        date: data.date, // ✅ 폼에서 선택한 날짜
        scheduleId: data.scheduleId || null,
        hasReceipt: false, // TODO: 영수증 업로드 기능 구현 예정
        receiptUrl: null, // TODO: 영수증 업로드 기능 구현 예정
      },
      {
        onSuccess: () => {
          console.log('✅ Expense created successfully');
          onSuccess?.();
          router.back();
        },
      },
    );
  };

  const onInvalid = () => {
    console.log('Form validation failed');
  };

  const handleSubmit = () => {
    void form.handleSubmit(onValid, onInvalid)();
  };

  return {
    form,
    isPending,
    onSubmit: handleSubmit,
  };
};
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useCreateTrip } from '@/entities/trip';
import { useRouter } from 'expo-router';
import { City } from './geonames.api';
import { generateId } from '@/shared/services/id/ulid';
import { dateToISODateTime } from '@/shared/lib/datetime';
import { getCurrencyByCountryCode } from '@/shared/lib/country-currency';

// Zod 스키마로 폼 검증 정의
const tripFormSchema = z
  .object({
    startDate: z.string().min(1, '시작일을 선택해주세요'),
    endDate: z.string().min(1, '종료일을 선택해주세요'),
  })
  .refine(
    (data) => {
      if (!data.startDate || !data.endDate) return true;
      const start = new Date(data.startDate);
      const end = new Date(data.endDate);
      return end >= start;
    },
    {
      message: '종료일은 시작일 이후여야 합니다',
      path: ['endDate'],
    },
  );

type TripFormData = z.infer<typeof tripFormSchema>;

export const useCreateTripForm = (city: City) => {
  const router = useRouter();
  const [pickerVisible, setPickerVisible] = useState(false);
  const [currentPicker, setCurrentPicker] = useState<'start' | 'end' | null>(null);

  const form = useForm<TripFormData>({
    resolver: zodResolver(tripFormSchema),
    defaultValues: {
      startDate: '',
      endDate: '',
    },
    mode: 'onChange',
  });

  const { mutate: createTrip, isPending } = useCreateTrip();

  const startDate = form.watch('startDate');

  const handleShowPicker = (pickerType: 'start' | 'end') => {
    setCurrentPicker(pickerType);
    setPickerVisible(true);
  };

  const handleSelectDate = (date: string) => {
    if (currentPicker === 'start') {
      form.setValue('startDate', date, { shouldValidate: true });
    } else {
      form.setValue('endDate', date, { shouldValidate: true });
    }
    setPickerVisible(false);
  };

  const handleClosePicker = () => {
    setPickerVisible(false);
  };

  const onValid = (data: TripFormData) => {
    createTrip(
      {
        id: generateId(), // ✅ 외부에서 ID 생성
        name: `${city.name} 여행`,
        destination: city.name,
        country: city.country,
        baseCurrency: getCurrencyByCountryCode(city.countryCode),
        latitude: city.latitude,
        longitude: city.longitude,
        cityId: city.id,
        startDate: dateToISODateTime(data.startDate), // ✅ ISO datetime 변환
        endDate: dateToISODateTime(data.endDate), // ✅ ISO datetime 변환
      },
      {
        onSuccess: () => {
          router.push('/(tabs)');
        },
      },
    );
  };

  const onInvalid = () => {
    console.log('Form validation failed');
  };

  return {
    form,
    isPending,
    pickerVisible,
    currentPicker,
    startDate,
    handleShowPicker,
    handleSelectDate,
    onSubmit: form.handleSubmit(onValid, onInvalid),
    onClosePicker: handleClosePicker,
  };
};
import { getTripActivationStatus, hasAnyActivatedTrip } from './metadata';
import { OfflineError } from './errors';
import { networkStore } from '@/shared/store/network';

interface RouteOperations<T> {
  local: () => Promise<T>;
  remote: () => Promise<T>;
}

function assertRemoteAvailable(offlineMessage: string, tripId?: string) {
  const status = networkStore.realStatus;

  if (status === 'online') {
    return;
  }

  throw new OfflineError(
    status === 'unknown' ? '인터넷 연결을 아직 확인하지 못했어요. 잠시 후 다시 시도해주세요.' : offlineMessage,
    { action: status === 'unknown' ? 'ONLINE_REQUIRED' : 'ACTIVATE_PROMPT', tripId },
  );
}

function assertWritesAllowed() {
  if (networkStore.override !== null) {
    throw new OfflineError('네트워크 화면 테스트 중에는 저장·삭제할 수 없어요. 강제 설정을 해제해주세요.', {
      action: 'ONLINE_REQUIRED',
    });
  }
}

/** Trip 조회의 기존 분기는 전역 활성 여행 존재 여부를 사용한다. */
export async function routeTripQuery<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  if (hasActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요');
  return await operations.remote();
}

/** Schedule·Expense 조회는 소속 여행의 활성 여부로 분기한다. */
export async function routeChildQuery<T>(tripId: string, operations: RouteOperations<T>): Promise<T> {
  const isActivated = await getTripActivationStatus(tripId);

  if (isActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요', tripId);
  return await operations.remote();
}

/** Trip 쓰기의 기존 분기는 전역 활성 여행 존재 여부를 사용한다. */
export async function routeTripMutation<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  assertWritesAllowed();

  if (hasActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 수정할 수 있어요');
  return await operations.remote();
}

/** Schedule·Expense 쓰기는 소속 여행의 활성 여부로 분기한다. */
export async function routeChildMutation<T>(tripId: string, operations: RouteOperations<T>): Promise<T> {
  const isActivated = await getTripActivationStatus(tripId);

  assertWritesAllowed();

  if (isActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 수정할 수 있어요', tripId);
  return await operations.remote();
}
