import { View, Text, type ViewProps, type TextProps } from 'react-native';
import { cn } from '@repo/ui';

// ========================================
// Field Compound Component (form 규칙 준수)
// ========================================

type FieldRootProps = ViewProps;
type FieldTitleProps = TextProps;
type FieldElementsBoxProps = ViewProps;
type FieldDescriptionProps = TextProps;
type FieldMessageProps = TextProps;

/**
 * Field.Root - 단일 필드를 감싸는 최상위 컨테이너
 */
function FieldRoot({ className, ...props }: FieldRootProps) {
  return <View className={cn('flex-col gap-2xs', className)} {...props} />;
}

/**
 * Field.Title - 필드의 제목/레이블
 */
function FieldTitle({ className, ...props }: FieldTitleProps) {
  return <Text className={cn('text-label text-foreground font-medium', className)} {...props} />;
}

/**
 * Field.ElementsBox - 입력 요소(TextInput 등)를 감싸는 컨테이너
 * 가로/세로 정렬 처리
 */
function FieldElementsBox({ className, ...props }: FieldElementsBoxProps) {
  return <View className={cn('flex-col gap-2xs', className)} {...props} />;
}

/**
 * Field.Description - 필드에 대한 추가 정보 제공
 */
function FieldDescription({ className, ...props }: FieldDescriptionProps) {
  return <Text className={cn('text-label text-muted-foreground', className)} {...props} />;
}

/**
 * Field.Message - 유효성 검사 에러 메시지 표시
 */
function FieldMessage({ className, ...props }: FieldMessageProps) {
  return <Text className={cn('text-label text-destructive', className)} {...props} />;
}

// Compound Component 구성
export const Field = Object.assign(FieldRoot, {
  Title: FieldTitle,
  ElementsBox: FieldElementsBox,
  Description: FieldDescription,
  Message: FieldMessage,
});
import { useEffect, useRef, useState } from 'react';
import { useAppPolicy } from './useAppPolicy';
import { useRealNetworkStatus } from '@/shared/store/network';

type ContentQuery = {
  isLoading: boolean;
  isError: boolean;
  refetch: () => Promise<{ isError: boolean; error: unknown }>;
};

type Recovery = {
  tripId?: string;
  blocked: boolean;
  hadOffline: boolean;
  phase: 'idle' | 'pending' | 'error';
};

/** 이전 서버 캐시는 보존하고, 현재 여행의 복구 조회가 성공할 때 내용을 다시 연다. */
export function useTripContentAccess(tripId: string | undefined, query: ContentQuery) {
  const policy = useAppPolicy(tripId);
  const realStatus = useRealNetworkStatus();
  const [recovery, setRecovery] = useState<Recovery>({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
  const [notice, setNotice] = useState<string | null>(null);
  const latest = useRef({ tripId, realStatus });
  latest.current = { tripId, realStatus };
  const requestVersion = useRef(0);
  const refetch = useRef(query.refetch);
  refetch.current = query.refetch;

  useEffect(() => {
    if (recovery.tripId !== tripId) {
      requestVersion.current += 1;
      setNotice(null);
      setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
      return;
    }
    if (!tripId || policy.activationStatus !== 'inactive') {
      if (recovery.blocked) {
        requestVersion.current += 1;
        setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
      }
      return;
    }

    if (realStatus !== 'online') {
      setNotice(null);
      requestVersion.current += 1;
      setRecovery((current) => ({
        ...current,
        blocked: true,
        hadOffline: current.hadOffline || realStatus === 'offline',
        phase: 'idle',
      }));
      return;
    }
    if (!recovery.blocked || recovery.phase !== 'idle') return;

    const version = ++requestVersion.current;
    setRecovery((current) => ({ ...current, phase: 'pending' }));
    refetch.current().then(
      (result) => {
        if (
          version !== requestVersion.current ||
          latest.current.tripId !== tripId ||
          latest.current.realStatus !== 'online'
        )
          return;
        if (result.isError) {
          setRecovery((current) => ({ ...current, phase: 'error' }));
        } else {
          if (recovery.hadOffline) setNotice('연결이 복구되어 여행 내용을 다시 불러왔어요.');
          setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
        }
      },
      () => {
        if (version === requestVersion.current && latest.current.tripId === tripId) {
          setRecovery((current) => ({ ...current, phase: 'error' }));
        }
      },
    );
  }, [
    tripId,
    realStatus,
    policy.activationStatus,
    recovery.tripId,
    recovery.blocked,
    recovery.phase,
    recovery.hadOffline,
  ]);

  useEffect(
    () => () => {
      requestVersion.current += 1;
    },
    [],
  );

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(null), 3500);
    return () => clearTimeout(timer);
  }, [notice]);

  const awaitingRecovery =
    recovery.tripId === tripId && recovery.blocked && realStatus === 'online' && policy.activationStatus === 'inactive';
  const status = !policy.content.allowed
    ? 'restricted'
    : awaitingRecovery
      ? recovery.phase === 'error'
        ? 'error'
        : 'loading'
      : query.isLoading
        ? 'loading'
        : query.isError
          ? 'error'
          : 'ready';

  const retry = () => {
    if (policy.activationStatus === 'error') policy.retryActivation();
    else if (awaitingRecovery) setRecovery((current) => ({ ...current, phase: 'idle' }));
    else query.refetch();
  };

  return { status, permission: policy.content, notice, retry };
}
import { View } from 'react-native';
import { Calendar, CalendarProps, Drawer, Pressable } from '@repo/ui';

type DatePickerProps = {
  visible?: boolean;
  onClose: () => void;
  onSelectDate: (date: string) => void;
} & CalendarProps;

export default function DatePicker({ visible = true, onClose, onSelectDate, ...props }: DatePickerProps) {
  return (
    <Drawer isOpen={visible} onClose={onClose} title='날짜 선택'>
      {/* Calendar */}
      <Calendar
        onDayPress={(day) => {
          onSelectDate(day.dateString);
        }}
        {...props}
      />

      {/* Footer Button */}
      <View className='pt-lg pb-xl'>
        <Pressable variant='default' onPress={onClose} className='w-full'>
          확인
        </Pressable>
import { create } from 'zustand';

interface TripStore {
  selectedTripId: string | null;
  setSelectedTripId: (tripId: string | null) => void;
}

/**
 * 전역 여행 선택 상태 관리 Store
 *
 * - 현재 선택된 여행 ID 저장
 * - TripSelector와 연동
 * - 기본값은 메인 여행 (TripSelector에서 자동 설정)
 *
 * @example
 * ```tsx
 * const { selectedTripId, setSelectedTripId } = useTripStore();
 *
 * // 여행 선택
 * setSelectedTripId('trip-id');
 *
 * // 현재 선택된 여행 사용
 * router.push(`/create-expense?tripId=${selectedTripId}`);
 * ```
 */
export const useTripStore = create<TripStore>((set) => ({
  selectedTripId: null,
  setSelectedTripId: (tripId) => set({ selectedTripId: tripId }),
}));

